/**
 * n8n Code node (JavaScript)
 * Transforms input like:
 *   [{ output: "[{...}]\n\n---\n\n**References:** ..."}]
 * into:
 *   [{ action: "parse", response: { output: [ ... ] } }]
 */

function extractFirstJsonArray(text) {
  if (typeof text !== 'string') return null;

  // Find first '['
  const start = text.indexOf('[');
  if (start < 0) return null;

  // Scan forward to find the matching closing ']' for the first JSON array.
  let depth = 0;
  let inString = false;
  let escape = false;

  for (let i = start; i < text.length; i++) {
    const ch = text[i];

    if (inString) {
      if (escape) {
        escape = false;
      } else if (ch === '\\') {
        escape = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }

    if (ch === '"') {
      inString = true;
      continue;
    }

    if (ch === '[') depth++;
    if (ch === ']') depth--;

    if (depth === 0) {
      // i is the index of the matching closing bracket
      return text.slice(start, i + 1);
    }
  }

  return null;
}

function safeJsonParse(jsonText) {
  try {
    return JSON.parse(jsonText);
  } catch (e) {
    return null;
  }
}

// Input handling: support either $json.output OR a nested "output" string.
const input = $input.all();

const outItems = [];

for (const item of input) {
  const j = item.json ?? {};

  // Common cases:
  // 1) j.output is already an array -> keep it
  // 2) j.output is a string containing JSON + refs -> extract JSON array and parse
  // 3) j.output is missing but j.response?.output exists -> keep it
  let topics = null;

  if (Array.isArray(j.output)) {
    topics = j.output;
  } else if (typeof j.output === 'string') {
    const arrText = extractFirstJsonArray(j.output);
    if (arrText) topics = safeJsonParse(arrText);
  } else if (j.response && Array.isArray(j.response.output)) {
    topics = j.response.output;
  }

  // Validate shape: should be an array of objects with title/rationale/hook
  if (!Array.isArray(topics)) {
    outItems.push({
      json: {
        action: "parse",
        response: { output: [] },
        error: "Could not parse topics array from input",
        rawPreview: typeof j.output === 'string' ? j.output.slice(0, 300) : null,
      }
    });
    continue;
  }

  // Clean each topic: keep only the three keys, coerce to strings, drop nulls
  const cleaned = topics
    .filter(t => t && typeof t === 'object')
    .map(t => ({
      title: String(t.title ?? "").trim(),
      rationale: String(t.rationale ?? "").trim(),
      hook: String(t.hook ?? "").trim(),
    }))
    .filter(t => t.title || t.rationale || t.hook);

  outItems.push({
    json: {
      action: "parse",
      response: {
        output: cleaned
      }
    }
  });
}

return outItems;

