parameters.jsCode:
// Normalize upstream outputs
const contentOut = $('Write Post JSON').first().json.output;
const hashtagOut = $('Generate Hashtags').first().json.output;

// Build main post body
const postContentBase =
  contentOut.topic + `\n\n` +
  contentOut.what_happened + `\n\n` +
  contentOut.why_it_happened + `\n\n` +
  contentOut.solution_and_takeaway;

// Normalize hashtags (handles array or object-with-indexes)
let hashtags = [];

if (Array.isArray(hashtagOut.Hashtags)) {
  hashtags = hashtagOut.Hashtags;
} else if (typeof hashtagOut.Hashtags === 'object') {
  hashtags = Object.values(hashtagOut.Hashtags);
}

// Join hashtags into LinkedIn-friendly line
const hashtagLine = hashtags.length
  ? `${hashtags.join(' ')}`
  : '';

// Final post content
const postContent = postContentBase;

return [{
  json: {
    ...$json,
    "post title": contentOut.topic,
    "post content": postContent,
    "hastags": hashtagLine,
    "image description": contentOut.image_description
  }
}];

